static Future<void> _openQuote(final BuildContext context, final GetQuoteArguments args,
    {final bool fromQuotePage = false}) {
  final String? current = ModalRoute.of(context)?.settings.name;
  final bool onQuote = current == MoGetQuoteNavigationStrings.getQuoteScreen ||
      current == GetQuotePaths.quotePath;
