  if (hasMountedScreen || _recovering) return false; // a full or mini chart owns the WebView
  _log('release ($reason) from ${_currentState.name}');
  _ackTimer?.cancel();
  _pendingTickJs.clear();
  await destroyCall();
  _setState(ChartState.initial);
  webViewGeneration.value++; // any later screen mounts a fresh platform view
  return true;
}

